<?php
namespace App\Jobs;
use App\Models\Examination;use App\Reports\Pdf\NonCadreInteractivePdfReport;use App\Models\ReportingExportRun;use App\Services\Documents\DocxPlaceholderTemplateService;use App\Services\NonCadre\Reporting\NonCadreReportingService;use App\Services\Reporting\ReportExportFileStore;use App\Support\Examinations\ExaminationConnectionManager;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\File;use Throwable;
final class ProcessNonCadreReportingExport implements ShouldQueue{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public int $tries=1;public int $timeout=0;public function __construct(public readonly int $examinationId,public readonly int $exportRunId,public readonly int $allocationRunId){$this->onQueue('imports');}
public function handle(ExaminationConnectionManager $connections,NonCadreReportingService $reports,ReportExportFileStore $files,DocxPlaceholderTemplateService $docx,NonCadreInteractivePdfReport $pdf):void{$exam=Examination::query()->findOrFail($this->examinationId);$connections->configure($exam);try{$x=ReportingExportRun::query()->where('module','non_cadre_reporting')->findOrFail($this->exportRunId);$source=$reports->requireReady();if((int)$source->id!==$this->allocationRunId)throw new \RuntimeException('NC4 authority changed after this export was queued.');$x->forceFill(['status'=>'running','phase'=>'GENERATING','progress_percent'=>15,'progress_message'=>'Generating Non-Cadre reporting export.','started_at'=>now()])->save();$p=(array)$x->parameters;if($x->export_type==='TXT'){$path=$files->outputPath('non-cadre-reporting',$x->id,'txt');File::put($path,$reports->txtContent($source,(int)($p['registrations_per_line']??8),(string)($p['report_title']??'Final Non-Cadre Allocation'),(string)$exam->name));$name='non-cadre-final-allocation-'.now()->format('Ymd-His').'.txt';$mime='text/plain; charset=UTF-8';}elseif($x->export_type==='PDF'){$generated=$pdf->generate($reports,(string)$x->scope,(string)($p['mode']??'verification'),isset($p['post_code'])?(string)$p['post_code']:null,(string)$exam->name);$path=$files->outputPath('non-cadre-reporting',$x->id,'pdf');File::put($path,$generated['content']);$name=$generated['filename'];$mime='application/pdf';}elseif($x->export_type==='DOCX'){$template=(string)($p['template_path']??'');if(!is_file($template))throw new \RuntimeException('Queued DOCX template is missing.');$path=$files->outputPath('non-cadre-reporting',$x->id,'docx');$docx->fill($template,$path,$reports->docxReplacements($source,(string)$exam->name,(string)($p['result_date']??now()->format('d-m-Y')),(int)($p['registrations_per_line']??8)));$name='non-cadre-final-allocation-'.now()->format('Ymd-His').'.docx';$mime='application/vnd.openxmlformats-officedocument.wordprocessingml.document';$files->forget($template);}else throw new \RuntimeException('Unsupported NC5 export type.');$x->forceFill(['status'=>'completed','phase'=>'COMPLETED','progress_percent'=>100,'progress_message'=>'Export completed.','file_path'=>$path,'file_name'=>$name,'file_mime'=>$mime,'file_hash'=>hash_file('sha256',$path)?:null,'completed_at'=>now()])->save();}catch(Throwable $e){ReportingExportRun::query()->whereKey($this->exportRunId)->update(['status'=>'failed','phase'=>'FAILED','progress_message'=>'Export failed.','failure_message'=>mb_substr($e->getMessage(),0,65000),'completed_at'=>now()]);throw$e;}finally{$connections->disconnect();}}}
